{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Evidence-informed wellness coaching to build sustainable habits, resilience, and daily energy. Lead magnet, programs, and case studies from {{COACH_NAME}}.">
  <link rel="icon" href="data:;base64,iVBORw0KGgo=">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="lux-gallery">
  <header class="site-header">
    <div class="container header-grid">
      <a class="brand" href="/"> 
        <svg width="42" height="42" viewBox="0 0 120 120" aria-hidden="true">
          <circle cx="60" cy="60" r="52" fill="#0f1724" />
          <text x="60" y="72" text-anchor="middle" font-family="sans-serif" font-size="48" fill="#fff">W</text>
        </svg>
        <span class="brand-text">{{BUSINESS_NAME}}</span>
      </a>
      <nav class="nav">
        <a href="/about.html">About</a>
        <a href="/programs.html">Paths</a>
        <a href="/services.html">Work</a>
        <a href="/pricing.html">Plans</a>
        <a href="/testimonials.html">Stories</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button class="nav-toggle" aria-label="Open menu">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section id="hero" class="hero container">
      <div class="hero-content">
        <h1 class="hero-title">Shift small routines into reliable results</h1>
        <p class="hero-sub">I combine behavioral science and habit frameworks to help busy professionals get measurable improvements in sleep, focus, and daily energy without radical life overhauls.</p>
        <div class="hero-cta">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/book.html">Book a discovery</a>
        </div>
        <form id="leadmagnet" class="lead-form" aria-label="Sign up for the guide">
          <label for="email">Get the Habit Starter Guide</label>
          <div class="form-row">
            <input id="email" name="email" type="email" placeholder="your@email.com" required>
            <button type="submit" class="btn small">Send me the guide</button>
          </div>
          <p class="muted">Free evidence-backed checklist from {{COACH_NAME}}, {{CREDENTIALS}} — delivered instantly.</p>
        </form>
      </div>
      <aside class="hero-art" aria-hidden="false">
        <!-- Inline hero svg -->
        <img src="assets/img/hero.svg" alt="Stylized wellness illustration">
      </aside>
    </section>

    <!-- MYTH VS TRUTH -->
    <section id="myth-truth" class="myth container">
      <h2 class="section-title">Myths and what actually works</h2>
      <div class="grid-2 myth-grid">
        <div class="card myth">
          <h3>Myth</h3>
          <p>"Quick fixes and strict rules are the fastest path to change."</p>
        </div>
        <div class="card truth">
          <h3>What the evidence shows</h3>
          <p>Small, repeated adjustments that fit your context create durable neural and behavioral change. We design micro-routines, not short-lived urgencies.</p>
        </div>
      </div>
      <p class="small-muted">As a scientist-guide, I frame interventions around reproducible habit loops and context design, never medical promises.</p>
    </section>

    <!-- PILLARS -->
    <section id="pillars" class="pillars container">
      <h2 class="section-title">Core frameworks I use</h2>
      <div class="pillars-grid">
        <article class="pillar">
          <svg class="icon" width="64" height="64" viewBox="0 0 100 100" aria-hidden="true">
            <rect x="12" y="12" width="76" height="76" rx="12" fill="#062b46" />
            <path d="M30 60 L45 35 L70 70" stroke="#fff" stroke-width="6" fill="none" stroke-linecap="round" stroke-linejoin="round" />
          </svg>
          <h3>Habit Architecture</h3>
          <p>We map cues, ease the friction, and anchor new actions to existing routines so the behavior persists.</p>
        </article>

        <article class="pillar">
          <svg class="icon" width="64" height="64" viewBox="0 0 100 100" aria-hidden="true">
            <circle cx="50" cy="50" r="38" fill="#08304a" />
            <path d="M35 55 L45 43 L65 64" stroke="#fff" stroke-width="5" fill="none" stroke-linecap="round" />
          </svg>
          <h3>Measurement & Scaling</h3>
          <p>Small metrics — sleep score, energy index, streak — let us iterate and scale what works reliably.</p>
        </article>

        <article class="pillar">
          <svg class="icon" width="64" height="64" viewBox="0 0 100 100" aria-hidden="true">
            <rect x="14" y="18" width="72" height="64" rx="8" fill="#0a3b58" />
            <path d="M28 56 L42 36 L60 54" stroke="#fff" stroke-width="5" fill="none" stroke-linecap="round" />
          </svg>
          <h3>Context Design</h3>
          <p>We reduce decision fatigue by shaping your environment and routines to cue positive actions automatically.</p>
        </article>
      </div>
    </section>

    <!-- CASE STUDIES -->
    <section id="case-studies" class="case-studies container">
      <h2 class="section-title">Measured outcomes</h2>
      <p class="lede">Three anonymized examples of progress from focused, 12-week engagements.</p>
      <div class="gallery">
        <figure class="case">
          <img src="assets/img/avatar.svg" alt="Client A avatar" />
          <figcaption>
            <strong>Executive: regained 75 minutes daily focus</strong>
            <p>Through micro-break routines and sleep-window consistency, attention blocks lengthened without extra work hours.</p>
          </figcaption>
        </figure>

        <figure class="case">
          <img src="assets/img/pattern.svg" alt="Client B avatar" />
          <figcaption>
            <strong>Freelancer: stabilized week-to-week energy</strong>
            <p>We introduced a simple pacing protocol and predictable meal+movement anchors to avoid midweek dips.</p>
          </figcaption>
        </figure>

        <figure class="case">
          <img src="assets/img/avatar.svg" alt="Client C avatar" />
          <figcaption>
            <strong>Parent-career balance: consistent morning routine</strong>
            <p>Shifting the cue environment and reducing friction led to a 5x increase in routine adherence after six weeks.</p>
          </figcaption>
        </figure>
      </div>
    </section>

    <!-- FAQ -->
    <section id="faq" class="faq container">
      <h2 class="section-title">Quick questions answered</h2>
      <div class="faq-list">
        <details>
          <summary>How soon will I see results?</summary>
          <div class="answer">Expect measurable shifts in awareness and small wins within 2–4 weeks; durable habit formation typically takes 6–12 weeks depending on complexity.</div>
        </details>
        <details>
          <summary>Is this medical advice?</summary>
          <div class="answer">No. Coaching focuses on behavior, routines, and practical frameworks. If you have medical concerns we recommend consulting a licensed clinician.</div>
        </details>
        <details>
          <summary>Do you work with remote clients?</summary>
          <div class="answer">Yes. The programs are designed for remote delivery with clear weekly tasks, measurement, and regular reviews.</div>
        </details>
      </div>
    </section>

    <!-- CTA -->
    <section id="cta" class="final-cta container">
      <div class="cta-panel">
        <h2>Start with a clear, evidence-first plan</h2>
        <p>Book a 20-minute clarity call with {{COACH_NAME}}, {{CREDENTIALS}} to map one immediate habit you can actually keep.</p>
        <div class="cta-actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/contact.html">Ask a question</a>
        </div>
        <p class="muted">Serving clients in {{CITY}}, {{STATE}} and remotely worldwide.</p>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="container footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p class="muted">Science-led coaching for sustainable routines.</p>
      </div>
      <nav class="footer-nav">
        <a href="/about.html">About</a>
        <a href="/programs.html">Programs</a>
        <a href="/pricing.html">Pricing</a>
        <a href="/book.html">Book</a>
      </nav>
      <div class="contact">
        <a href="tel:{{PHONE}}">{{PHONE}}</a>
        <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
      </div>
    </div>
    <div class="legal">© <span id="year"></span> {{BUSINESS_NAME}} — All rights reserved.</div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
