{"path":"assets/css/styles.css","content":"/* Lux Gallery theme — restrained motion, generous spacing */
:root{
  --bg:#071022; --card:#07182a; --muted:#9fb0c2; --accent:#08a1c8; --accent-2:#0cf7ff; --white:#ffffff; --radius:12px; --container:1100px;
  --glass: rgba(255,255,255,0.04);
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:var(--white);background:linear-gradient(180deg,#021223 0%,#061425 60%);-webkit-font-smoothing:antialiased}
.container{max-width:var(--container);margin:0 auto;padding:28px}
.header-grid{display:flex;align-items:center;justify-content:space-between;gap:16px}
.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:var(--white)}
.brand-text{font-weight:700}
.nav{display:flex;gap:18px;align-items:center}
.nav a{color:var(--muted);text-decoration:none;font-weight:600}
.nav a.cta{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#021022;padding:10px 14px;border-radius:10px}
.nav-toggle{display:none;background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--white);padding:8px 12px;border-radius:8px}

.hero{display:grid;grid-template-columns:1fr 440px;gap:34px;align-items:center;padding-top:36px;padding-bottom:36px}
.hero-title{font-size:42px;line-height:1.02;margin:0 0 12px 0;color:var(--white)}
.hero-sub{color:var(--muted);margin:0 0 18px}
.hero-cta .btn{margin-right:12px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none;font-weight:700}
.btn.primary{background:var(--accent);color:#021022}
.btn.ghost{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--white)}
.btn.small{padding:8px 12px}
.lead-form{margin-top:18px}
.lead-form label{display:block;color:var(--muted);font-size:13px;margin-bottom:6px}
.form-row{display:flex;gap:8px}
.form-row input{flex:1;padding:10px;border-radius:10px;border:1px solid rgba(255,255,255,0.06);background:transparent;color:var(--white)}
.small-muted{color:var(--muted);font-size:13px}
.hero-art img{width:100%;height:auto;border-radius:20px;box-shadow:0 10px 30px rgba(2,18,34,0.6)}

.section-title{font-size:22px;margin-bottom:12px}
.myth .myth-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.card{background:var(--card);padding:18px;border-radius:14px}
.card h3{margin:0 0 8px}
.muted{color:var(--muted)}

.pillars-grid{display:flex;gap:18px;margin-top:12px}
.pillar{background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));padding:18px;border-radius:14px;flex:1}
.pillar h3{margin:10px 0}
.icon{display:block}

.case-studies .gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:12px}
.case{background:var(--card);padding:14px;border-radius:12px}
.case img{width:100%;height:140px;object-fit:cover;border-radius:8px}
.case figcaption{margin-top:8px}

.faq-list details{background:var(--card);padding:12px;border-radius:10px;margin-bottom:8px}
.faq-list summary{cursor:pointer;font-weight:700}
.answer{margin-top:8px;color:var(--muted)}

.final-cta{margin-top:28px}
.cta-panel{background:linear-gradient(90deg, rgba(8,161,200,0.08), rgba(12,247,255,0.04));padding:22px;border-radius:14px}
.cta-actions{margin-top:12px}

.site-footer{margin-top:40px;padding-top:18px;padding-bottom:28px;border-top:1px solid rgba(255,255,255,0.03);background:transparent}
.footer-grid{display:flex;justify-content:space-between;align-items:center}
.footer-nav a{display:block;color:var(--muted);text-decoration:none;margin-bottom:6px}
.contact a{display:block;color:var(--muted);text-decoration:none}
.legal{text-align:center;color:var(--muted);font-size:13px;margin-top:14px}

@media (max-width:900px){
  .hero{grid-template-columns:1fr;}
  .nav{display:none}
  .nav-toggle{display:block}
  .case-studies .gallery{grid-template-columns:1fr}
  .pillars-grid{flex-direction:column}
}

/* subtle animations */
.hero-art img{transform:translateY(0);transition:transform 600ms cubic-bezier(.2,.8,.2,1)}
.hero-art img:hover{transform:translateY(-8px)}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // year
  var y=document.getElementById('year'); if(y) y.textContent=new Date().getFullYear();

  // mobile nav toggle
  var btn=document.querySelector('.nav-toggle'), nav=document.querySelector('.nav');
  if(btn && nav){
    btn.addEventListener('click',function(){
      nav.classList.toggle('open');
      if(nav.classList.contains('open')){nav.style.display='flex'} else {nav.style.display=''}
    });
  }

  // lead magnet submission (mock)
  var lead=document.getElementById('leadmagnet');
  if(lead){
    lead.addEventListener('submit',function(e){
      e.preventDefault();
      var email=lead.querySelector('input[name="email"]').value;
      if(!email) return;
      // simple validation
      lead.querySelector('.btn.small').textContent='Sending…';
      setTimeout(function(){
        lead.querySelector('.btn.small').textContent='Sent';
        lead.reset();
        setTimeout(function(){lead.querySelector('.btn.small').textContent='Send me the guide';},2500);
      },900);
    });
  }

  // smooth scroll for internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      var target=document.querySelector(this.getAttribute('href'));
      if(target){e.preventDefault();target.scrollIntoView({behavior:'smooth',block:'start'});}
    });
  });

  // accessible FAQ: toggle details with keyboard
  document.querySelectorAll('.faq-list details summary').forEach(function(s){
    s.addEventListener('keydown',function(e){if(e.key==='Enter' || e.key===' '){e.preventDefault(); this.parentElement.open = !this.parentElement.open;}});
  });
});"} 
